const ThemeContext = createContext({ theme: DARK_THEME, mode: "dark", toggle: () => {} });
function useTheme() {
  return useContext(ThemeContext);
}

function ThemeProvider({ children }) {
  const getSystemMode = () =>
    typeof window !== "undefined" && window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches
      ? "dark"
      : "light";

  const [mode, setMode] = useState(getSystemMode);
  const manualRef = useRef(false);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const handler = (e) => {
      if (!manualRef.current) setMode(e.matches ? "dark" : "light");
    };
    if (mq.addEventListener) mq.addEventListener("change", handler);
    else mq.addListener(handler);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener("change", handler);
      else mq.removeListener(handler);
    };
  }, []);

  const toggle = () => {
    manualRef.current = true;
    setMode((m) => (m === "dark" ? "light" : "dark"));
  };

  const theme = mode === "dark" ? DARK_THEME : LIGHT_THEME;
  const value = useMemo(() => ({ theme, mode, toggle }), [theme, mode]);

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

