function ContributionChart() {
  const { theme: T } = useTheme();
  const [state, setState] = useState({ status: "loading", weeks: [], total: 0, streak: 0, longest: 0 });

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(`https://github-contributions-api.jogruber.de/v4/${GH_USER}?y=last`);
        if (!res.ok) throw new Error("bad response");
        const data = await res.json();
        const contributions = Array.isArray(data) ? data : data.contributions || [];
        if (!contributions.length) throw new Error("empty");

        const byDate = {};
        contributions.forEach((c) => {
          byDate[c.date] = c;
        });

        const today = new Date(contributions[contributions.length - 1].date);
        const start = new Date(today);
        start.setDate(start.getDate() - 370);
        while (start.getDay() !== 0) start.setDate(start.getDate() - 1);

        const weeks = [];
        let cursor = new Date(start);
        let total = 0;
        while (cursor <= today) {
          const week = [];
          for (let d = 0; d < 7; d++) {
            const key = cursor.toISOString().slice(0, 10);
            const rec = byDate[key];
            if (cursor <= today) {
              week.push({ date: key, count: rec ? rec.count : 0, level: rec ? rec.level : 0 });
              if (rec) total += rec.count;
            } else {
              week.push(null);
            }
            cursor.setDate(cursor.getDate() + 1);
          }
          weeks.push(week);
        }

        const flat = contributions.slice().sort((a, b) => (a.date < b.date ? -1 : 1));
        let longest = 0;
        let run = 0;
        let current = 0;
        for (let i = 0; i < flat.length; i++) {
          if (flat[i].count > 0) {
            run += 1;
            longest = Math.max(longest, run);
          } else {
            run = 0;
          }
        }
        for (let i = flat.length - 1; i >= 0; i--) {
          if (flat[i].count > 0) current += 1;
          else break;
        }

        if (!cancelled) setState({ status: "ready", weeks, total, streak: current, longest });
      } catch (e) {
        if (!cancelled) setState({ status: "error", weeks: [], total: 0, streak: 0, longest: 0 });
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const levelColor = (level) => {
    if (level === 0) return T.surface2;
    const alphas = [0, 0.32, 0.55, 0.78, 1];
    const a = alphas[Math.min(level, 4)];
    return `rgba(${T.emeraldRgb},${a})`;
  };

  if (state.status === "loading") {
    return (
      <div style={{ color: T.textFaint, fontFamily: "'JetBrains Mono', monospace", fontSize: 13 }}>
        fetching contribution history for @{GH_USER}…
      </div>
    );
  }

  if (state.status === "error") {
    return (
      <div
        style={{
          border: `1px dashed ${T.border}`,
          padding: "20px 24px",
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 13,
          color: T.textMuted,
        }}
      >
        Live activity feed unavailable right now.{" "}
        <a href={`https://github.com/${GH_USER}`} style={{ color: T.emerald }}>
          View @{GH_USER} on GitHub →
        </a>
      </div>
    );
  }

  const months = [];
  let lastMonth = -1;
  state.weeks.forEach((week, wi) => {
    const first = week.find((d) => d);
    if (!first) return;
    const m = new Date(first.date).getMonth();
    if (m !== lastMonth) {
      months.push({ index: wi, label: new Date(first.date).toLocaleString("en", { month: "short" }) });
      lastMonth = m;
    }
  });

  return (
    <div>
      <div style={{ display: "flex", gap: 40, marginBottom: 28, flexWrap: "wrap" }}>
        {[
          ["Contributions, last year", state.total],
          ["Current streak", `${state.streak}d`],
          ["Longest streak", `${state.longest}d`],
        ].map(([label, val]) => (
          <div key={label}>
            <div style={{ fontFamily: "'Space Grotesk', sans-serif", fontSize: 26, fontWeight: 600, color: T.text }}>
              {val}
            </div>
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: T.textFaint, marginTop: 2 }}>
              {label}
            </div>
          </div>
        ))}
      </div>

      <div style={{ overflowX: "auto", paddingBottom: 8 }}>
        <div style={{ display: "inline-block" }}>
          <div style={{ display: "flex", marginLeft: 26, marginBottom: 6 }}>
            {state.weeks.map((_, wi) => {
              const m = months.find((mo) => mo.index === wi);
              return (
                <div
                  key={wi}
                  style={{
                    width: 12,
                    fontFamily: "'JetBrains Mono', monospace",
                    fontSize: 10,
                    color: T.textFaint,
                  }}
                >
                  {m ? m.label : ""}
                </div>
              );
            })}
          </div>
          <div style={{ display: "flex", gap: 2 }}>
            <div style={{ display: "flex", flexDirection: "column", gap: 2, marginRight: 6, width: 20 }}>
              {["", "Mon", "", "Wed", "", "Fri", ""].map((d, i) => (
                <div key={i} style={{ height: 10, fontFamily: "'JetBrains Mono', monospace", fontSize: 9, color: T.textFaint }}>
                  {d}
                </div>
              ))}
            </div>
            {state.weeks.map((week, wi) => (
              <div key={wi} style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                {week.map((day, di) =>
                  day ? (
                    <div
                      key={di}
                      title={`${day.date}: ${day.count} contribution${day.count === 1 ? "" : "s"}`}
                      style={{
                        width: 10,
                        height: 10,
                        background: levelColor(day.level),
                        borderRadius: 2,
                      }}
                    />
                  ) : (
                    <div key={di} style={{ width: 10, height: 10 }} />
                  )
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 14 }}>
        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10, color: T.textFaint }}>Less</span>
        {[0, 1, 2, 3, 4].map((l) => (
          <div key={l} style={{ width: 10, height: 10, borderRadius: 2, background: levelColor(l) }} />
        ))}
        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10, color: T.textFaint }}>More</span>
      </div>
    </div>
  );
}

function RepoList() {
  const { theme: T } = useTheme();
  const [repos, setRepos] = useState({ status: "loading", items: [] });

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(`https://api.github.com/users/${GH_USER}/repos?sort=updated&per_page=8`);
        if (!res.ok) throw new Error("bad response");
        const data = await res.json();
        const items = data
          .filter((r) => !r.fork)
          .sort((a, b) => new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime())
          .slice(0, 4);
        if (!cancelled) setRepos({ status: "ready", items });
      } catch (e) {
        if (!cancelled) setRepos({ status: "error", items: [] });
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  if (repos.status === "loading") return null;
  if (repos.status === "error" || repos.items.length === 0) return null;

  return (
    <div style={{ marginTop: 40 }}>
      <div
        style={{
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 11,
          letterSpacing: "0.1em",
          textTransform: "uppercase",
          color: T.textFaint,
          marginBottom: 14,
        }}
      >
        Recently touched repositories
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 12 }}>
        {repos.items.map((r) => (
          <a
            key={r.id}
            href={r.html_url}
            target="_blank"
            rel="noreferrer"
            style={{
              display: "block",
              padding: "14px 16px",
              border: `1px solid ${T.border}`,
              textDecoration: "none",
              color: T.text,
            }}
          >
            <div style={{ fontFamily: "'Space Grotesk', sans-serif", fontSize: 14, fontWeight: 600, marginBottom: 4 }}>
              {r.name}
            </div>
            <div
              style={{
                fontFamily: "'Source Serif 4', serif",
                fontSize: 13,
                color: T.textMuted,
                marginBottom: 10,
                minHeight: 34,
              }}
            >
              {r.description || "No description provided."}
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: T.textFaint }}>
              <span>{r.language || "—"}</span>
              <span>★ {r.stargazers_count}</span>
            </div>
          </a>
        ))}
      </div>
    </div>
  );
}

